import type { SoundParams } from "../audio/types";

export function generateWebAudioSnippet(params: SoundParams): string {
  return `// Procedural Sound Effect: ${params.name}
// Generated by code-as-assets Studio
function play${params.name.replace(/[^a-zA-Z0-9]/g, "")}(audioCtx = new (window.AudioContext || window.webkitAudioContext)()) {
  const now = audioCtx.currentTime;
  const startFreq = ${params.baseFrequency};
  const endFreq = ${(params.baseFrequency * Math.pow(2, params.pitchSlide / 12)).toFixed(1)};
  const duration = ${(params.attack + params.decay + params.release).toFixed(3)};

  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  const filter = audioCtx.createBiquadFilter();

  osc.type = '${params.waveType === "noise" ? "sawtooth" : params.waveType}';
  filter.type = '${params.filterType}';
  filter.frequency.setValueAtTime(${params.brightness}, now);
  filter.Q.setValueAtTime(${params.resonance}, now);

  // Pitch sweep
  osc.frequency.setValueAtTime(startFreq, now);
  osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), now + ${Math.min(params.attack + params.decay, 1.5).toFixed(3)});

  // Volume envelope
  gain.gain.setValueAtTime(0.0001, now);
  gain.gain.exponentialRampToValueAtTime(${(params.volume / 100).toFixed(2)}, now + ${Math.max(0.001, params.attack).toFixed(3)});
  gain.gain.exponentialRampToValueAtTime(${Math.max(0.0001, (params.volume / 100) * params.sustain).toFixed(3)}, now + ${(params.attack + params.decay).toFixed(3)});
  gain.gain.exponentialRampToValueAtTime(0.00001, now + duration);

  osc.connect(filter);
  filter.connect(gain);
  gain.connect(audioCtx.destination);

  osc.start(now);
  osc.stop(now + duration + 0.05);
}
`;
}

export function downloadBlob(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}
